-- handwritten: runtime/client/mixins/Player.lua

do

local PlayerId, PlayerPedId, GetPlayerPed = PlayerId, PlayerPedId, GetPlayerPed
local NetworkIsPlayerActive, DoesEntityExist = NetworkIsPlayerActive, DoesEntityExist
local GetPlayerServerId, GetPlayerFromServerId = GetPlayerServerId, GetPlayerFromServerId
local setmetatable, rawget, tostring, tonumber, type, error = setmetatable, rawget, tostring, tonumber, type, error
local wrapPed = rt.lazyWrap("Ped")

-- Other players are { serverId = n }: their local index changes when they leave / enter scope, so it is
-- resolved on every access.
---@type table<integer, fx.Player> By server id
local remoteCache = setmetatable({}, { __mode = "v" })

-- id: the local index, -1 when the player is out of scope. handle (what the natives receive) refuses -1:
-- most player natives read -1 as the LOCAL player.
---@param self fx.Player
---@return integer
getters.id = function(self) return GetPlayerFromServerId(rawget(self, "serverId")) end
---@param self fx.Player
---@return integer
getters.handle = function(self)
  local idx = GetPlayerFromServerId(rawget(self, "serverId"))
  if idx == -1 then error(("%s is not in scope on this client (no local player index)"):format(tostring(self)), 3) end
  return idx
end

-- `ped` is recomputed on every access: it changes on death, respawn and model change
---@param self fx.Player
---@return fx.Ped?
getters.ped = function(self)
  local idx = GetPlayerFromServerId(rawget(self, "serverId"))
  if idx == -1 then return nil end -- GetPlayerPed(-1) would return the LOCAL ped
  return wrapPed(GetPlayerPed(idx))
end

---@type table<fx.Player, fx.StateBag>
local statesCache = setmetatable({}, { __mode = "k" })
---@param self fx.Player
---@return fx.StateBag
getters.states = function(self)
  local s = statesCache[self]
  if s == nil then
    s = rt.states.player(rawget(self, "serverId"), false)
    statesCache[self] = s
  end
  return s
end
getters.state = getters.states

---@param a fx.Player
---@param b fx.Player
---@return boolean
T.eq = function(a, b) return a.serverId == b.serverId end
---@param self fx.Player
---@return string
T.tostring = function(self) return ("Player(%s)"):format(tostring(self.serverId)) end

-- the local player is the static table itself
---@type fx.StateBag?
local localStates
---@type table<string, fun(): any> Getters of the local player (the static table)
local localGetters = {
  handle = PlayerId,
  id = PlayerId,
  ---@return integer
  serverId = function() return GetPlayerServerId(PlayerId()) end,
  ---@return fx.Ped
  ped = function() return wrapPed(PlayerPedId()) --[[@as fx.Ped]] end, -- the local player always has a ped
  ---@return fx.StateBag
  states = function()
    if localStates then return localStates end
    local id = GetPlayerServerId(PlayerId())
    local s = rt.states.player(id, true)
    if id > 0 then localStates = s end -- before the session starts the server id is not known yet
    return s
  end,
}
localGetters.state = localGetters.states

---@type fx.PlayerStatic
local Local
---@param _ any The static table (__call)
---@param serverId any
---@return fx.Player?
local function fromServerId(_, serverId)
  serverId = tonumber(serverId)
  if not serverId then return nil end
  local idx = GetPlayerFromServerId(serverId)
  if idx == -1 then return nil end
  if idx == PlayerId() then return Local end
  local o = remoteCache[serverId]
  if o == nil then
    o = setmetatable({ serverId = serverId }, T.mt)
    remoteCache[serverId] = o
  end
  return o
end

---@param idx integer|fx.Player|nil Local index, as returned by the natives
---@return fx.Player?
T.wrap = function(idx)
  if idx == nil or idx == -1 then return nil end
  if type(idx) == "table" then return idx end
  ---@cast idx integer
  if idx == PlayerId() then return Local end
  return fromServerId(nil, GetPlayerServerId(idx))
end

---@param idx any
---@return fx.Player?
statics.fromIndex = function(idx)
  idx = tonumber(idx)
  if idx == nil or idx < 0 then return nil end
  return T.wrap(idx)
end

local GetActivePlayers = GetActivePlayers
---@return fx.Player[]
statics.all = function()
  ---@type fx.Player[]
  local out = {}
  for _, idx in ipairs(GetActivePlayers()) do
    local p = statics.fromIndex(idx)
    if p then out[#out + 1] = p end
  end
  return out
end

---@param fmt string
---@param ... any
local function errorf(fmt, ...) error(fmt:format(...), 3) end
T.staticMT = {
  __call = fromServerId,
  ---@param t fx.PlayerStatic
  ---@param k string
  ---@return any
  __index = function(t, k)
    local lg = localGetters[k]
    if lg ~= nil then return lg() end
    local sg = staticGetters[k]
    if sg ~= nil then return sg() end
    local m = methods[k]
    if m ~= nil then return m end
    local g = getters[k]
    if g ~= nil then return g(t) end
    return nil
  end,
  ---@param t fx.PlayerStatic
  ---@param k string
  ---@param v any
  __newindex = function(t, k, v)
    local s = setters[k]
    if s ~= nil then s(t, v); return end
    local ss = staticSetters[k]
    if ss ~= nil then ss(v); return end
    if localGetters[k] or staticGetters[k] or getters[k] or methods[k] or statics[k] then errorf("Player.%s is read-only", tostring(k)) end
    errorf("Player has no property '%s'", tostring(k))
  end,
  ---@return string
  __tostring = function() return ("Player(local, %s)"):format(tostring(GetPlayerServerId(PlayerId()))) end,
}

---@param static table<string, any>
T.afterFinalize = function(static) Local = static --[[@as fx.PlayerStatic]] end

-- Client scripts start during the loading screen, before the session exists; the player becomes active later.
---@return boolean
local function isReady()
  return NetworkIsPlayerActive(PlayerId()) and DoesEntityExist(PlayerPedId())
end

---@type fx.Promise<fx.PlayerStatic>?
local readyPromise
---@param _ fx.PlayerStatic
---@param timeoutMs? integer
---@return fx.Promise<fx.PlayerStatic>
statics.readyAsync = function(_, timeoutMs)
  if timeoutMs == nil then
    if not readyPromise then
      readyPromise = rt.waitUntil("Player:readyAsync", isReady, math.huge, Local)
    end
    return readyPromise
  end
  return rt.waitUntil("Player:readyAsync", isReady, timeoutMs, Local)
end

-- msgpack ext 42: works even when the player is out of scope (no index / ped then)
---@param serverId integer?
---@return fx.Player?
T.decode = function(serverId)
  if not serverId then return nil end
  if serverId == GetPlayerServerId(PlayerId()) then return Local end
  local o = remoteCache[serverId]
  if o == nil then
    o = setmetatable({ serverId = serverId }, T.mt)
    remoteCache[serverId] = o
  end
  return o
end

end

return rt.finalize(T)
